import { itemDetailUrl } from "@arsenyx/shared/warframe/catalog-files"
import type { BrowseCategory } from "@arsenyx/shared/warframe/types"
import { notFound } from "@tanstack/react-router"

import type { DetailItem } from "@/lib/catalog"

import { staticDataQuery } from "./static-data-query"

/** Slugs are generated by the data pipeline and are always lowercase
 *  alphanumeric + dashes. Anything else is a hand-crafted URL: without this
 *  check a `../`-bearing slug normalizes to a different `/data/*.json` file
 *  and feeds wrong-shaped JSON into the editor instead of 404ing. */
const SLUG_RE = /^[a-z0-9-]+$/

export const itemQuery = (category: BrowseCategory, slug: string) => {
  const query = staticDataQuery<DetailItem>(
    itemDetailUrl(category, encodeURIComponent(slug)),
    "failed to load item",
    { notFoundOn404: true },
  )
  if (SLUG_RE.test(slug)) return query
  return {
    ...query,
    queryFn: (): Promise<DetailItem> => {
      throw notFound()
    },
  }
}
